<?php
declare(strict_types=1); require_once __DIR__.'/../includes/admin-auth.php'; require_super_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){ require_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['id']??0); if($action==='delete'&&$id){db_query('UPDATE products SET is_active=0 WHERE id=?',[$id]); flash('success','Product archived.');} elseif($action==='save'){ $name=trim((string)($_POST['name']??'')); $price=(float)($_POST['price']??0); $cat=(int)($_POST['category_id']??0); if($name&&$price>0&&$cat){$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($name)).'-'.time(); if($id) db_query('UPDATE products SET name=?,price=?,category_id=? WHERE id=?',[$name,$price,$cat,$id]); else db_query('INSERT INTO products(category_id,name,slug,sku,price) VALUES(?,?,?,?,?)',[$cat,$name,$slug,'BFM-'.time(),$price]); flash('success','Product saved.');}}
redirect('admin/products.php'); }
$products=db_all('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC'); $cats=db_all('SELECT id,name FROM categories WHERE is_active=1 ORDER BY sort_order'); $pageTitle='Products'; require __DIR__.'/../includes/header.php'; ?><section class="container page-section"><div class="admin-nav"><div><p class="eyebrow">Admin</p><h1>Products</h1></div><a class="btn" href="<?=e(url('admin/index.php'))?>">Dashboard</a></div><form method="post" class="form-stack" style="max-width:700px;border:1px solid #ddd;padding:1rem;margin-bottom:2rem"><?=csrf_field()?><input type="hidden" name="action" value="save"><label>Name<input name="name" required></label><label>Category<select name="category_id" required><?php foreach($cats as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach; ?></select></label><label>Price (Rs.)<input type="number" name="price" min="1" step="1" required></label><button class="btn btn-primary">Add product</button></form><div style="overflow:auto"><table class="admin-table"><tr><th>Name</th><th>Category</th><th>Price</th><th>Action</th></tr><?php foreach($products as $p): ?><tr><td><?=e($p['name'])?></td><td><?=e($p['category_name'])?></td><td><?=e(money($p['sale_price']?:$p['price']))?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-sm">Archive</button></form></td></tr><?php endforeach; ?></table></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
